+    be16(&mut sub, 2 * segs);
+    for _ in 0..3 {
+        be16(&mut sub, 0); // search hints, unused by the reader
+    }
+    chars.iter().for_each(|&(c, _)| be16(&mut sub, c));
+    be16(&mut sub, 0);
+    chars.iter().for_each(|&(c, _)| be16(&mut sub, c));
+    chars.iter().for_each(|&(c, gid)| be16(&mut sub, if c == 0xFFFF { 1 } else { gid.wrapping_sub(c) }));
+    chars.iter().for_each(|_| be16(&mut sub, 0));
